    SponsorsModule,
    AdvertisementsModule,
    ClubMatchSessionsModule,
    SocialSessionsModule,
    SocialLocationsModule,
    FriendshipsModule,
    ZaloModule,
  ],
  controllers: [AppController],
  providers: [
    AppService,
    {
      provide: APP_GUARD,
      useClass: AppKeyGuard,
    },
…
